  "credential": "Fondation du Dr Peter McCullough (éducation des médecins)",
  "notPhysician": true,
  "notPhysicianLabel": "Fondation, pas un médecin",
  "claim": "Spray salin et gargarisme à l’eau salée, deux fois par jour",
  "quote": "Twice a Day, Nose and Throat — The Hygiene Step Nobody Teaches\n\nRespiratory viruses land in the NOSE AND THROAT first. That makes those surfaces the one place you can intervene before an infection takes hold. Saline nasal spray and a gargle, twice daily — salt water, salt water with a few drops of iodine, or xylitol-based. Randomized work on irrigation and gargling shows SHORTENED ILLNESS DURATION. Costs almost nothing. Nobody teaches it.\n\n#MedicalFreedom",
  "gist": "Les virus respiratoires arrivent d’abord dans le nez et la gorge. Spray nasal salin et gargarisme à l’eau salée deux fois par jour : les essais sur le lavage et le gargarisme montrent une maladie plus courte.",
  "date": "2026-10-19T18:31:13.000Z",
