  "quote": "@DoctorChrisVT raises an important point-you don't need to treat a fever, which is the body's response to help fight infection. Treat the child, if they are miserable+not drinking then treat but if running around as normal you dont have to! #Fever #Health\nhttps://t.co/jWxrTvl9wW",
  "gist": "Pas besoin de traiter la fièvre : c’est la réponse du corps pour combattre l’infection.",
  "date": "2018-05-23T08:37:30.000Z",
